let catalog, movies=[], heroIndex=1, heroTimer, listState={}, currentMovie=null, episode=1, localVideo=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k)=>{try{return JSON.parse(localStorage.getItem('sa-'+k)||'[]')}catch{return []}};
const save=(k,v)=>localStorage.setItem('sa-'+k,JSON.stringify(v));
const catIds={'全部分类':'','电影':'13','连续剧':'12','综艺':'11','短剧':'16','动漫':'14','纪录片':'15'};
const listUrl=(cat='')=>'/movie/list?cat_id='+(catIds[cat]||cat)+'&position=movie';
const movieUrl=m=>'/movie/detail/'+(m.slug||m.id)+'-'+m.id;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3000)}
function header(home=false){$('#header').className=home?'home-header':'';$('#header').innerHTML=`<div class="header-inner"><a class="logo" href="/" aria-label="SA影视首页"><img src="${catalog.logo}" alt="SA影视"></a><div class="nav-dropdown"><button class="nav-trigger" data-action="menu">影视⌄</button><nav class="dropdown">${Object.keys(catIds).map(c=>`<a href="${listUrl(c)}">${c}</a>`).join('')}<a href="/mine/help">帮助中心</a></nav></div><a class="rank-link" href="/movie/rank">排行榜</a><button class="vip" data-action="vip">VIP</button><nav class="mobile-nav"><a href="/">主页</a>${['电影','连续剧','综艺','动漫'].map(c=>`<a href="${listUrl(c)}">${c==='连续剧'?'电视剧':c}</a>`).join('')}</nav><form class="search-form" role="search"><input name="q" aria-label="搜索影片" placeholder="搜索您想看的影片" autocomplete="off"><button aria-label="搜索" type="submit">⌕</button><div class="search-suggest"><h3>热门搜索</h3>${['醒来','交锋','重器','凡人修仙传','哪吒之魔童闹海'].map((n,i)=>`<a href="/search?q=${encodeURIComponent(n)}">${i+1}　${n}</a>`).join('')}</div></form><div class="header-end"><button class="history" data-action="history"><span>▣</span>看过</button><button class="login-pill login-sparkle" data-action="login" type="button"><span class="dots_border" aria-hidden="true"></span><svg class="sparkle" width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><path class="path" d="M12 2 14.8 9.2 22 12 14.8 14.8 12 22 9.2 14.8 2 12 9.2 9.2Z"/><path class="path" d="m20 1 1 2 2 1-2 1-1 2-1-2-2-1 2-1Z"/></svg><span class="text_button">登录</span></button></div></div>`;
$('#footer').innerHTML=`<div class="footer-inner"><div><a class="logo" href="/"><img src="${catalog.logo}" alt="SA影视"></a><p>Copyright © 2018 https://samh.tw All rights reserved</p><p>SA影视参考页面复刻</p></div><div><h3>关于</h3><a href="/mine/help">关于我们</a><a href="/mine/help">联系我们</a><a href="/mine/history">观看记录</a></div><div><h3>政策</h3><a href="/mine/help">使用条款</a><a href="/mine/help">滥用报告</a><a href="/mine/help">隐私政策</a></div><div><h3>其他</h3><a href="/mine/help">常见问题</a><a href="/mine/favorites">我的收藏</a><a href="${listUrl()}">全部影片</a></div></div><div class="footer-bottom">影片信息来自参考站公开页面 · 浏览与收藏记录仅保存在本机</div>`}
function card(m){return `<article class="movie-card"><a href="${movieUrl(m)}" aria-label="查看${esc(m.name)}"><div class="poster"><img src="${m.img}" alt="${esc(m.name)}" loading="lazy" decoding="async"><span class="score">${esc(m.score)}</span><span class="duration">${esc(m.duration)}</span><span class="hover-play" aria-hidden="true">▶</span></div><span class="card-title">${esc(m.name)}</span></a><div class="hover-info"><img src="${m.img}" alt="" loading="lazy"><div class="hover-info-copy"><h3>${esc(m.name)}</h3><p>${esc(m.category)}　${esc(m.issue_year||m.issue_date?.slice(0,4)||'')}</p><p class="synopsis">${esc(m.description||'暂无简介')}</p><div><button data-fav="${m.id}">☆ 收藏</button><a href="${movieUrl(m)}">详情 ›</a></div></div></div><p class="card-meta">${esc(m.tags?.map(t=>t.name).join(' ')||m.category)}</p></article>`}
function section(s,i,feature=false){return `<section class="${feature?'feature-section':'catalog-section'}"><div class="section-title">${s.icon?`<img src="${s.icon}" alt="">`:''}<h2>${esc(s.name)}</h2>${feature?'':`<a class="more" href="${listUrl(s.items[0]?.category)}">更多 ›</a>`}</div><div class="${feature?'feature-track':'movie-grid'}" id="row-${i}">${s.items.map(card).join('')}</div>${feature?`<button class="row-arrow prev" data-row="${i}" data-step="-1" aria-label="上一张">‹</button><button class="row-arrow next" data-row="${i}" data-step="1" aria-label="下一张">›</button>`:''}</section>`}
function home(){header(true);const b=catalog.banners[heroIndex];$('#app').innerHTML=`<section class="hero" aria-label="推荐影片轮播"><a id="hero-link" href="${bannerLink(b)}"><img class="hero-image" src="${b.content}" alt="${esc(b.name)}" fetchpriority="high"></a><div class="hero-copy" aria-live="off">${heroCopy(b)}</div><div class="hero-picker"><button class="hero-arrow" data-hero-step="-1" aria-label="上一部推荐影片">‹</button><div class="hero-thumbs" aria-label="选择推荐影片">${catalog.banners.map((x,i)=>`<button class="hero-thumb ${i===heroIndex?'active':''}" aria-pressed="${i===heroIndex}" aria-label="切换到${esc(x.name)}" data-slide="${i}"><span class="hero-poster"><img src="${bannerMovie(x)?.img||x.content}" alt="" loading="lazy"><span class="hover-play" aria-hidden="true">▶</span></span><span class="hero-caption">${esc(x.name)}</span></button>`).join('')}</div><button class="hero-arrow" data-hero-step="1" aria-label="下一部推荐影片">›</button></div></section><nav class="hero-nav"><div class="categories">${catalog.categories.map(c=>`<a href="${listUrl(c.name)}">${c.name}</a>`).join('')}<a href="${listUrl()}">更多</a></div><span class="theme-label">▦ 推荐主题</span><div class="theme-links">${catalog.themes.map(t=>`<a href="/theme-detail/${t.id}">${esc(t.name)} ›</a>`).join('')}</div></nav><div class="mobile-only mobile-categories">${catalog.categories.map(c=>`<a href="${listUrl(c.name)}">${c.name}</a>`).join('')}</div><div class="home-content">${catalog.home_recommends.map((s,i)=>section(s,i,true)).join('')}${catalog.sections.map((s,i)=>section(s,i+3)).join('')}</div>`;
if(!matchMedia('(prefers-reduced-motion: reduce)').matches)heroTimer=setInterval(()=>{const hero=$('.hero');if(hero&&!hero.matches(':hover')&&!hero.contains(document.activeElement)&&!document.hidden)slide(heroIndex+1)},7000);
}
function bannerLink(b){if(b.link.startsWith('/movie/detail/')){const m=movies.find(m=>b.link.endsWith(m.id));if(m)return movieUrl(m);return '/search?q='+encodeURIComponent(b.name)}return b.link.startsWith('/movie/list')?b.link:listUrl('动漫')}
function bannerMovie(b){return movies.find(m=>b.link.endsWith(m.id))}
function heroCopy(b){const m=bannerMovie(b);const facts=m?[m.score&&m.score!=='0.0'?`★ ${m.score} 分`:null,m.heat?`热度 ${m.heat}`:null,m.duration].filter(Boolean):[];const meta=m?[m.actor?.split(/[,，、/]/).slice(0,2).join('　'),m.tags?.slice(0,2).map(t=>t.name).join(' ')||m.category].filter(Boolean).join('　'):'';return `<h1>${esc(b.name)}</h1>${facts.length?`<div class="hero-facts">${facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`:''}${meta?`<p class="hero-meta">${esc(meta)}</p>`:''}<p class="hero-tagline">${esc(b.tag_text||m?.description||b.description||'精选影片，精彩呈现')}</p><a class="play-button" href="${bannerLink(b)}"><span aria-hidden="true">▶</span>立即播放</a>`}
function slide(i){heroIndex=(i+catalog.banners.length)%catalog.banners.length;const b=catalog.banners[heroIndex];if(!$('.hero'))return;$('.hero-image').src=b.content;$('.hero-image').alt=b.name;$('#hero-link').href=bannerLink(b);$('.hero-copy').innerHTML=heroCopy(b);document.querySelectorAll('[data-slide]').forEach(e=>{const active=+e.dataset.slide===heroIndex;e.classList.toggle('active',active);e.setAttribute('aria-pressed',String(active));if(active){const rail=$('.hero-thumbs');if(e.offsetLeft<rail.scrollLeft||e.offsetLeft+e.offsetWidth>rail.scrollLeft+rail.clientWidth)rail.scrollTo({left:e.offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}})}
function route(){clearInterval(heroTimer);if(localVideo){URL.revokeObjectURL(localVideo);localVideo=null;}const path=location.pathname;currentMovie=null;document.title='SA影视 - 电影电视剧动漫综艺';if(path==='/')home();else{header();if(path.startsWith('/movie/detail/'))detail(path);else if(path==='/movie/rank')rank();else if(path.startsWith('/theme-detail/'))themePage(path);else if(path==='/search'||path==='/movie/list')listing();else if(path.startsWith('/mine/'))mine(path);else $('#app').innerHTML='<div class="empty"><h1>页面不存在</h1><p>这个链接暂时没有对应内容。</p><a class="primary" href="/">返回首页</a></div>';}document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.opacity='.25';img.alt='图片暂时无法加载'},{once:true}))}
function openModal(body){const d=$('#modal');d.innerHTML='<button class="close-modal" aria-label="关闭" data-action="close">×</button>'+body;if(!d.open)d.showModal()}
function login(){openModal(`<h2>登录 SA影视</h2><form id="login-form"><label>账号<input name="account" autocomplete="username" placeholder="请输入账号" required></label><label>密码<input name="password" type="password" autocomplete="current-password" placeholder="请输入密码" required minlength="6"></label><p class="error" id="login-error" hidden></p><button class="primary" style="width:100%">登录</button></form><p class="hint muted">当前为页面复刻，尚未连接账号服务。请勿输入真实账号密码。你仍可直接浏览影片、保存本机收藏。</p>`)}
function listing(){const p=new URLSearchParams(location.search);listState={cat:p.get('cat_id')?.split(',')[0]||'',tag:p.get('tag')||'',area:p.get('area')||'',language:p.get('language')||'',year:p.get('year')||'',status:p.get('status')||'',sort:p.get('sort')||'',q:p.get('q')||'',page:Math.max(1,+(p.get('page')||1))};renderListing()}
function filterRow(label,key,values){return `<div class="filter-row"><span class="filter-label">${label}</span><div class="filter-options">${values.map(([label,value])=>`<button data-filter="${key}" data-value="${esc(value)}" class="${listState[key]===value?'selected':''}">${label}</button>`).join('')}</div></div>`}
function renderListing(){const s=listState;let result=movies.filter(m=>(!s.cat||catIds[m.category]===s.cat)&&(!s.q||[m.name,m.actor,m.director].some(v=>v?.toLowerCase().includes(s.q.toLowerCase())))&&(!s.tag||m.tags?.some(t=>t.name===s.tag))&&(!s.area||m.area===s.area)&&(!s.language||m.language===s.language)&&(!s.status||(s.status==='全集'?m.duration.startsWith('全'):m.duration.startsWith('更新')))&&(!s.year||(s.year==='更早'?+(m.issue_year||m.issue_date?.slice(0,4))<2025:(m.issue_year||m.issue_date?.slice(0,4))===s.year)));
if(s.sort==='评分高低')result.sort((a,b)=>+b.score-+a.score);else if(s.sort==='人气高低')result.sort((a,b)=>parseFloat(b.heat||0)-parseFloat(a.heat||0));else if(s.sort==='上映时间')result.sort((a,b)=>(b.issue_date||'').localeCompare(a.issue_date||''));
const theme=catalog.themes.find(t=>location.pathname.endsWith(t.id));let title=s.q?`“${esc(s.q)}”的搜索结果`:theme?esc(theme.name):Object.keys(catIds).find(c=>catIds[c]===s.cat)||'全部影片';if(theme){const n=catalog.themes.indexOf(theme);result=movies.filter(m=>n===2?m.category==='短剧':n===3?m.category==='动漫':n===6?/悬疑|惊悚|犯罪/.test(m.tags?.map(t=>t.name).join('')):m.category==='连续剧');}
const tags=[...new Set(movies.filter(m=>!s.cat||catIds[m.category]===s.cat).flatMap(m=>m.tags?.map(t=>t.name)||[]))];const pages=Math.max(1,Math.ceil(result.length/32));s.page=Math.min(s.page,pages);
$('#app').innerHTML=`<div class="page listing-page"><h1 class="${s.q?'':'sr-only'}">${title}</h1>${s.q||theme?'':`<div class="list-top"><div class="filter-panel">${filterRow('全部分类','cat',Object.entries(catIds))}${filterRow('全部标签','tag',[['全部',''],...tags.map(t=>[t,t])])}${filterRow('全部地区','area',[['全部',''],...['内地剧','美剧','日剧','韩剧','港剧','泰剧','台剧'].map(t=>[t,t])])}${filterRow('全部语言','language',[['全部',''],...['国语','英语','日语','韩语','粤语'].map(t=>[t,t])])}${filterRow('全部年份','year',[['全部',''],['今年','2026'],['去年','2025'],['更早','更早']])}${filterRow('全部状态','status',[['全部',''],['全集','全集'],['连载','连载']])}</div><a class="list-ad" href="/" aria-label="SA影视首页"><img src="${catalog.ad}" alt="锁定潮流视界，阅尽千万剪影"></a></div>`}<div class="results-bar"><div class="sort-options">${['','上映时间','人气高低','评分高低'].map(x=>`<button class="${s.sort===x?'selected':''}" data-filter="sort" data-value="${x}">${x||'全部'}</button>`).join('')}</div><p class="muted">共有 ${result.length} 个筛选结果</p></div><div class="movie-grid">${result.slice((s.page-1)*32,s.page*32).map(card).join('')||'<div class="empty"><h2>暂无符合条件的影片</h2><p>试试其他关键词，或清除筛选条件。</p><button class="primary" data-action="reset-filters">清除筛选</button></div>'}</div>${pages>1?`<nav class="pagination" aria-label="分页"><button data-page="${s.page-1}" ${s.page===1?'disabled':''}>上一页</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${s.page===i+1?'selected':''}">${i+1}</button>`).join('')}<button data-page="${s.page+1}" ${s.page===pages?'disabled':''}>下一页</button></nav>`:''}</div>`;if(s.q)$('[name=q]').value=s.q;document.title=title.replace(/&[^;]+;/g,'')+' - SA影视';}
function detail(path){const id=path.split('-').pop();const m=movies.find(m=>m.id===id);if(!m){$('#app').innerHTML='<div class="empty"><h1>暂未收录这部影片</h1><p>可返回片库浏览已收录影片。</p><a class="primary" href="/movie/list">浏览片库</a></div>';return}currentMovie=m;episode=Math.max(1,+(new URLSearchParams(location.search).get('episode')||1));const hist=read('history').filter(x=>x.id!==m.id);hist.unshift({id:m.id,episode,date:new Date().toISOString()});save('history',hist.slice(0,80));document.title=m.name+' - SA影视';const count=+(m.duration.match(/\d+/)?.[0]||1);$('#app').innerHTML=`<div class="page detail-page"><div class="detail-layout"><div><div class="player" id="player"><img class="player-poster" src="${m.img}" alt=""><div class="player-title"><a href="/">‹</a><img src="${catalog.logo}" alt="SA FILM"><span>${esc(m.name)} · 第${episode}集</span></div><div class="player-message"><button class="primary" data-action="play">▶ 播放第${episode}集</button></div><div class="player-controls"><button data-action="prev-episode" aria-label="上一集">◀</button><button data-action="play" aria-label="播放">▶</button><button data-action="next-episode" aria-label="下一集">▶|</button><span>00:00 / --:--</span><span class="spacer"></span><button data-action="episodes">选集</button><select aria-label="播放速度" id="speed"><option value="1">倍速</option><option value="0.75">0.75×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option><option value="2">2×</option></select><button data-action="fullscreen" aria-label="全屏">⛶</button></div></div><div class="action-bar"><button data-action="like">赞</button><button data-action="dislike">踩</button><button data-action="favorite" class="${read('favorites').includes(m.id)?'active':''}">${read('favorites').includes(m.id)?'★ 已收藏':'☆ 收藏'}</button><button data-action="share">分享</button><button data-action="feedback">反馈</button></div><section class="detail-info"><h1>${esc(m.name)}</h1><p class="detail-meta">${esc(m.tags?.map(t=>t.name).join(' ')||m.category)}　 |　热度 ${esc(m.heat||'暂无数据')}　 |　${esc(m.score)} 分</p><div class="detail-description"><img src="${m.img}" alt="${esc(m.name)}"><div><p><b>上映：</b>${esc(m.issue_date||m.issue_year||'暂无数据')}</p><p><b>导演：</b>${esc(m.director||'暂无数据')}</p><p><b>主演：</b>${esc(m.actor||'暂无数据')}</p><p class="description"><b>简介：</b>${esc(m.description||'当前暂无简介')}</p><button data-action="expand-description">展开简介⌄</button></div></div></section><section class="episodes" id="episodes"><div class="episodes-head"><h2>选集</h2><button data-action="reverse-episodes">倒序 ↓</button></div><div class="episode-grid">${Array.from({length:count},(_,i)=>`<button class="${i+1===episode?'selected':''}" data-episode="${i+1}">第${i+1}集</button>`).join('')}</div></section><section class="catalog-section"><div class="section-title"><h2>推荐视频</h2></div><div class="movie-grid">${movies.filter(x=>x.category===m.category&&x.id!==m.id).slice(0,16).map(card).join('')}</div></section></div><aside class="related"><h3>相关内容</h3>${movies.filter(x=>x.category===m.category&&x.id!==m.id).slice(0,9).map(x=>`<a class="related-card" href="${movieUrl(x)}"><div class="card-media"><img src="${x.img}" alt="${esc(x.name)}" loading="lazy"><span class="hover-play" aria-hidden="true">▶</span></div><div class="copy"><h4>${esc(x.name)}</h4><p class="muted">${esc(x.category)}</p><span>${esc(x.score)}分　${esc(x.heat||'')}</span></div></a>`).join('')}</aside></div></div>`;}
function rank(cat='电影'){const rows=movies.filter(m=>m.category===cat).sort((a,b)=>parseFloat(b.heat||0)-parseFloat(a.heat||0)).slice(0,30);$('#app').innerHTML=`<div class="page"><h1>排行榜</h1><div class="rank-tabs">${['电影','连续剧','综艺','短剧','动漫'].map(c=>`<button data-rank="${c}" class="${cat===c?'selected':''}">${c}</button>`).join('')}</div><div class="rank-grid">${rows.map((m,i)=>`<a href="${movieUrl(m)}" class="rank-item"><span class="rank-number">${i+1}</span><div class="card-media"><img src="${m.img}" alt="${esc(m.name)}" loading="lazy"><span class="hover-play" aria-hidden="true">▶</span></div><div><h3>${esc(m.name)}</h3><span class="score" style="position:static">${esc(m.score)} 分</span><p>${esc(m.duration)}</p><p>热度 ${esc(m.heat||'暂无数据')}</p></div></a>`).join('')}</div></div>`}
function mine(path){if(path==='/mine/help'){$('#app').innerHTML=`<div class="page help"><h1>帮助中心</h1>${[['如何寻找影片？','通过顶部搜索框输入片名或演员，在分类页按类型、地区、年份筛选，也可以浏览排行榜。'],['为什么影片无法播放？','当前页面是界面复刻，尚未接入可用的授权播放源。播放器支持选择本机视频进行播放，视频不会上传。'],['收藏和观看记录保存在哪里？','收藏和浏览记录仅保存在当前浏览器中，清除浏览器数据后会消失。'],['可以使用原站账号登录吗？','不能。此页面没有连接原站账号服务，不会提交或保存你输入的账号密码。'],['隐私与反馈','本页面的搜索、收藏与观看记录仅在本机处理。反馈功能展示表单，但不会向原站发送信息。']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;return}const history=path==='/mine/history';const ids=history?read('history').map(x=>x.id):read('favorites');const selected=ids.map(id=>movies.find(m=>m.id===id)).filter(Boolean);$('#app').innerHTML=`<div class="page"><h1>个人中心</h1><nav class="collection-tabs"><a href="/mine/favorites" class="${history?'':'selected'}">我的收藏</a><a href="/mine/history" class="${history?'selected':''}">观看记录</a></nav>${history&&selected.length?'<button class="more" data-action="clear-history">清空观看记录</button>':''}<div class="movie-grid" style="margin-top:24px">${selected.map(card).join('')||`<div class="empty"><h2>暂无${history?'观看记录':'收藏'}</h2><p>${history?'浏览影片详情后会在这里显示。':'在影片详情页点击收藏，将喜欢的影片保存在这里。'}</p><a class="primary" href="/">去发现影片</a></div>`}</div></div>`}
function navigate(url){history.pushState({},'',url);route();window.scrollTo({top:0,behavior:'instant'})}
function updateFilter(){const p=new URLSearchParams();Object.entries(listState).forEach(([k,v])=>{if(v)p.set(k==='cat'?'cat_id':k,String(v))});history.replaceState({},'',location.pathname+'?'+p);renderListing()}
function setEpisode(n){if(!currentMovie)return;const count=+(currentMovie.duration.match(/\d+/)?.[0]||1);if(n<1||n>count){toast(n<1?'已经是第一集':'已经是最后一集');return}navigate(movieUrl(currentMovie)+'?episode='+n)}
function play(){const v=$('video');if(v){v.paused?v.play():v.pause();return}$('.player-message').innerHTML=`<h2>暂未接入播放源</h2><p>第 ${episode} 集的影片播放地址尚未配置。<br>可选择本机视频体验播放器，文件不会上传。</p><label class="local-file">选择本机视频<input type="file" accept="video/*" id="local-video"></label>`}
const actions={top:()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}),menu:()=>$('.dropdown').classList.toggle('open'),login,close:()=>$('#modal').close(),vip:()=>openModal('<h2>VIP 会员</h2><p class="muted">当前复刻页面尚未接入会员服务。</p><p class="hint">可直接浏览影片信息并使用本机收藏。会员开通与支付暂不可用。</p>'),history:()=>navigate('/mine/history'),favorite:()=>{if(!currentMovie)return;let f=read('favorites');const has=f.includes(currentMovie.id);f=has?f.filter(x=>x!==currentMovie.id):[...f,currentMovie.id];save('favorites',f);const b=$('[data-action=favorite]');b.classList.toggle('active',!has);b.textContent=has?'☆ 收藏':'★ 已收藏';toast(has?'已取消收藏':'已加入我的收藏')},like:()=>{const b=$('[data-action=like]');b.classList.toggle('active');$('[data-action=dislike]').classList.remove('active')},dislike:()=>{const b=$('[data-action=dislike]');b.classList.toggle('active');$('[data-action=like]').classList.remove('active')},share:async()=>{try{await navigator.clipboard.writeText(location.href);toast('链接已复制')}catch{openModal(`<h2>分享影片</h2><input readonly value="${esc(location.href)}" aria-label="影片链接"><p class="hint">复制此链接即可分享。</p>`)}},feedback:()=>openModal('<h2>播放反馈</h2><form id="feedback-form"><label>遇到的问题<textarea required name="feedback" rows="4" placeholder="请描述遇到的问题"></textarea></label><p class="hint muted">反馈服务尚未接入，此表单仅用于交互演示。</p><button class="primary">检查反馈</button><p class="error" id="feedback-error" hidden></p></form>'),play,episodes:()=>$('#episodes').scrollIntoView({behavior:'smooth'}),'prev-episode':()=>setEpisode(episode-1),'next-episode':()=>setEpisode(episode+1),fullscreen:()=>$('#player').requestFullscreen?.().catch(()=>toast('当前环境不支持全屏')),'expand-description':()=>{const p=$('.description');p.classList.toggle('expanded');$('[data-action=expand-description]').textContent=p.classList.contains('expanded')?'收起简介⌃':'展开简介⌄'},'reverse-episodes':()=>{const g=$('.episode-grid');[...g.children].reverse().forEach(e=>g.append(e))},'reset-filters':()=>{listState={cat:'',tag:'',area:'',language:'',year:'',status:'',sort:'',q:'',page:1};updateFilter()},'clear-history':()=>{save('history',[]);mine('/mine/history');toast('观看记录已清空')}};
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('/')&&!e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.getAttribute('href'));return}const b=e.target.closest('button');if(!b)return;if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.fav){const f=read('favorites'),id=b.dataset.fav,has=f.includes(id);save('favorites',has?f.filter(x=>x!==id):[...f,id]);b.textContent=has?'☆ 收藏':'★ 已收藏';toast(has?'已取消收藏':'已加入我的收藏');return}if(b.dataset.slide!==undefined){slide(+b.dataset.slide);clearInterval(heroTimer)}if(b.dataset.heroStep){clearInterval(heroTimer);slide(heroIndex+ +b.dataset.heroStep)}if(b.dataset.row){const row=$('#row-'+b.dataset.row);row.scrollBy({left:row.clientWidth*+b.dataset.step,behavior:'smooth'})}if(b.dataset.filter){listState[b.dataset.filter]=b.dataset.value;listState.page=1;updateFilter()}if(b.dataset.page){listState.page=+b.dataset.page;updateFilter();window.scrollTo({top:250,behavior:'smooth'})}if(b.dataset.rank)rank(b.dataset.rank);if(b.dataset.episode)setEpisode(+b.dataset.episode)});
document.addEventListener('keydown',e=>{if(!e.target.closest('.hero-thumbs')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();clearInterval(heroTimer);slide(e.key==='Home'?0:e.key==='End'?catalog.banners.length-1:heroIndex+(e.key==='ArrowRight'?1:-1));document.querySelector(`[data-slide="${heroIndex}"]`)?.focus({preventScroll:true})});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.matches('.search-form')){const q=new FormData(e.target).get('q').trim();if(q){e.target.querySelector('input').blur();navigate('/search?q='+encodeURIComponent(q))}else toast('请输入片名或演员')}if(e.target.id==='login-form'){const err=$('#login-error');err.hidden=false;err.textContent='账号服务尚未配置，无法登录。你的输入没有发送或保存。';e.target.querySelector('[name=password]').value=''}if(e.target.id==='feedback-form'){$('#feedback-error').hidden=false;$('#feedback-error').textContent='内容已填写，反馈服务尚未配置，未发送。'}});
document.addEventListener('change',e=>{if(e.target.id==='local-video'&&e.target.files[0]){if(localVideo)URL.revokeObjectURL(localVideo);localVideo=URL.createObjectURL(e.target.files[0]);const player=$('#player');player.innerHTML=`<video class="video-source" controls autoplay playsinline src="${localVideo}"></video>`;$('video').addEventListener('error',()=>toast('浏览器无法播放此格式，请选择 MP4 或 WebM'))}if(e.target.id==='speed'&&$('video'))$('video').playbackRate=+e.target.value});
window.addEventListener('popstate',route);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
try{const response=await fetch('/catalog.json');if(!response.ok)throw Error('catalog');catalog=await response.json();const all=catalog.home_recommends.flatMap(s=>s.items).concat(catalog.sections.flatMap(s=>s.items),catalog.extraMovies||[]);const map=new Map();for(const m of all){m.duration=m.duration||'暂无集数';m.tags=m.tags||[];m.category=typeof m.category==='object'?m.category.name:m.category;if(!map.has(m.name))map.set(m.name,m)}movies=[...map.values()];for(const b of catalog.banners){const m=movies.find(m=>m.name===b.name||m.name.replace('来','來')===b.name);if(m&&b.link.startsWith('/movie/detail/')){const full=b.link.split('/').pop();m.id=full.split('-').pop();m.slug=full.slice(0,full.lastIndexOf('-'))}}route()}catch(e){$('#app').innerHTML='<div class="empty"><h1>影片资料加载失败</h1><p>请检查网络后刷新页面。</p><button class="primary" onclick="location.reload()">重新加载</button></div>';console.error(e)}

function themePage(path){const t=catalog.themeDetails?.find(t=>path.endsWith(t.id));if(!t){listing();return}document.title=t.name+' - SA影视';$('#app').innerHTML=`<section class="theme-hero"><img src="${t.bg_img}" alt="${esc(t.name)}"></section><div class="page"><h1>${esc(t.name)}</h1><p class="theme-description">${esc(t.description)}</p>${t.blocks.map((block,i)=>section({...block,items:block.items.map(m=>movies.find(x=>x.name===m.name)||m)},'theme-'+i)).join('')}</div>`}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();document.modelContext.registerTool({name:'search_films',title:'搜索影片',description:'在当前片库中搜索片名或演员，打开搜索结果页面。',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||!input.query.trim())throw new Error('请输入搜索词');const query=input.query.trim();navigate('/search?q='+encodeURIComponent(query));return {query,results:movies.filter(m=>[m.name,m.actor,m.director].some(v=>v?.includes(query))).map(m=>({id:m.id,name:m.name})).slice(0,30)}}},{signal:lifecycle.signal});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
